private bool IsValidModal()
{
    ClearModalValidation();
    bool isOk = true;

    int taskTypeId = ParseInt(ddlTaskType.SelectedValue);
    if (taskTypeId <= 0)
    {
        SetFieldError(ddlTaskType, litErrTaskType, "Bạn phải chọn loại quyết định!");
        isOk = false;
    }

    if (!ValidateOptionalDate(txtDecidedDate, litErrDecidedDate, "Ngày quyết định không đúng định dạng (dd/MM/yyyy)."))
        isOk = false;

    if (!ValidateOptionalDate(txtTaskFrom, litErrTaskFrom, "Từ ngày không đúng định dạng (dd/MM/yyyy)."))
        isOk = false;

    if (!ValidateOptionalDate(txtTaskTo, litErrTaskTo, "Đến ngày không đúng định dạng (dd/MM/yyyy)."))
        isOk = false;

    if (!ValidateOptionalDate(txtEndTask_DecidedDate, litErrEndTask_DecidedDate, "Ngày QĐ miễn nhiệm không đúng định dạng (dd/MM/yyyy)."))
        isOk = false;

    DateTime? taskFrom = ParseNullableDate(txtTaskFrom.Text);
    DateTime? taskTo = ParseNullableDate(txtTaskTo.Text);
    if (taskFrom.HasValue && taskTo.HasValue && taskTo.Value < taskFrom.Value)
    {
        SetFieldError(txtTaskTo, litErrTaskTo, "Đến ngày không được nhỏ hơn từ ngày.");
        isOk = false;
    }

    return isOk;
}

private bool ValidateOptionalDate(TextBox txt, Literal litErr, string invalidFormatMessage)
{
    if (txt == null)
        return true;

    if (string.IsNullOrWhiteSpace(txt.Text))
        return true;

    if (ParseNullableDate(txt.Text).HasValue)
        return true;

    SetFieldError(txt, litErr, invalidFormatMessage);
    return false;
}

private void ClearModalValidation()
{
    SetFieldError(ddlTaskType, litErrTaskType, null);
    SetFieldError(txtDecidedDate, litErrDecidedDate, null);
    SetFieldError(txtTaskFrom, litErrTaskFrom, null);
    SetFieldError(txtTaskTo, litErrTaskTo, null);
    SetFieldError(txtEndTask_DecidedDate, litErrEndTask_DecidedDate, null);
}

private static void SetFieldError(WebControl input, Literal litErr, string message)
{
    if (litErr != null)
    {
        if (string.IsNullOrEmpty(message))
            litErr.Text = string.Empty;
        else
            litErr.Text = string.Format("<div class=\"empv2-field-error\">{0}</div>", HttpUtility.HtmlEncode(message));
    }

    if (input == null)
        return;

    string css = input.CssClass ?? string.Empty;
    if (css.IndexOf(" is-invalid", StringComparison.Ordinal) >= 0)
        css = css.Replace(" is-invalid", string.Empty);

    if (!string.IsNullOrEmpty(message))
        css = css.Trim() + " is-invalid";

    input.CssClass = css.Trim();
}

