using System;
using System.Data;
using System.Web;
using DCore;
using SimsObject;

namespace InformationWeb.Controls.Employee_V2
{
    /// <summary>
    /// Kiểm tra quyền sửa tab con trên Employee V2 (AllowEditToDate).
    /// </summary>
    public static class EmployeeV2TabCanEdit
    {
        public static bool CanEdit(HttpSessionState session)
        {
            if (session == null)
                return false;

            SessionUser objUser = session[Globals.USER] as SessionUser;
            if (objUser == null)
                return false;

            SIM_Teacher sim = new SIM_Teacher();
            DataTable dtbTeacherInfo = sim.GetDataTable("SIM_Teacher_Employee", "@TeacherID", objUser.UserName.ToLower());
            if (dtbTeacherInfo == null || dtbTeacherInfo.Rows.Count == 0)
                return true;

            DateTime allowEditToDate;
            if (DateTime.TryParse(dtbTeacherInfo.Rows[0]["AllowEditToDate"].ToString(), out allowEditToDate))
                return DateTime.Now <= allowEditToDate;

            return true;
        }
    }
}

using System;
using System.Globalization;
using System.Text;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using DCore;
using InformationWebObject;
using TKSObject;

namespace InformationWeb.Controls.Employee_V2
{
    public partial class TabCongTacEdit : ControlBase
    {
        private const string StoreTaskType = "HRS_TaskType_GETALL";
        private const string StorePosition = "GEN_Position_GETALL";

        private readonly HRS_Employee employeeDao = new HRS_Employee();

        public event EventHandler DataSaved;

        protected void Page_Load(object sender, EventArgs e)
        {
            RegisterClientScript();

            if (!IsPostBack)
            {
                LoadLookups();
                ApplyEditPermission();
            }
        }

        public void SetEmployeeContext(long employeeId, string employeeDisplay)
        {
            ViewState["EmpV2_CongTacEdit_EmployeeID"] = employeeId;
            ViewState["EmpV2_CongTacEdit_EmployeeDisplay"] = employeeDisplay ?? string.Empty;
            LoadEmployeePositionPrefill(employeeId);

            if (ddlTaskType.Items.Count <= 1)
                LoadLookups();

            ApplyEditPermission();
        }

        public void ClearValidationState()
        {
            ClearModalValidation();
            hidOpenModal.Value = string.Empty;
            udpAll.Update();
        }

        public void OpenForAdd()
        {
            ClearModalFields(true);
            txtTaskFrom.Text = DateTime.Today.ToString("dd/MM/yyyy", CultureInfo.InvariantCulture);
            hidOpenModal.Value = "1";
            udpAll.Update();
            RegisterShowModalScript();
        }

        public void OpenForEdit(long taskId)
        {
            if (taskId <= 0)
                return;

            ClearModalValidation();
            hdnTaskID.Value = taskId.ToString();
            txtEmployeeDisplay.Text = GetEmployeeDisplay();

            HRS_Task item = new HRS_Task();
            item.TaskID = taskId;
            if (!item.Get())
            {
                MsgBox.ShowWarning("Không lấy được thông tin công tác.");
                return;
            }

            EmployeeV2WebLookup.SelectValue(ddlTaskType, item.TaskTypeID);
            EmployeeV2WebLookup.SelectValue(ddlCurrentPosition, item.CurrentPositionID);
            EmployeeV2WebLookup.SelectValue(ddlPosition, item.PositionID);
            EmployeeV2WebLookup.SelectValue(ddlOtherPosition, item.OtherPositionID);

            txtDecidedNo.Text = SafeText(item.DecidedNo);
            txtDecidedDate.Text = FormatDateForInput(item.DecidedDate);
            txtTaskFrom.Text = FormatDateForInput(item.TaskFrom);
            txtTaskTo.Text = FormatDateForInput(item.TaskTo);
            chkIsSigned.Checked = item.IsSigned;
            txtDecidedDepartmentName.Text = SafeText(item.DecidedDepartmentName);
            txtDecidedFullName.Text = SafeText(item.DecidedFullName);
            txtToOfficeName.Text = SafeText(item.ToOfficeName);
            txtToDepartmentName.Text = SafeText(item.ToDepartmentName);
            txtWork.Text = SafeText(item.Work);
            txtDescription.Text = SafeText(item.Description);
            txtEndTask_DecidedNo.Text = SafeText(item.EndTask_DecidedNo);
            txtEndTask_DecidedDate.Text = FormatDateForInput(item.EndTask_DecidedDate);

            hidOpenModal.Value = "1";
            udpAll.Update();
            RegisterShowModalScript();
        }

        protected void btnSaveModal_Click(object sender, EventArgs e)
        {
            if (!EmployeeV2TabCanEdit.CanEdit(Session))
            {
                MsgBox.ShowWarning("Bạn không được phép lưu hoặc đã hết hạn chỉnh sửa.");
                return;
            }

            if (!IsValidModal())
            {
                hidOpenModal.Value = "1";
                udpAll.Update();
                RegisterShowModalScript();
                return;
            }

            long employeeId = GetEmployeeId();
            if (employeeId <= 0)
            {
                MsgBox.ShowWarning("Không xác định được nhân viên.");
                return;
            }

            SessionUser objUser = Session[Globals.USER] as SessionUser;
            if (objUser == null)
            {
                MsgBox.ShowWarning("Phiên làm việc đã hết. Vui lòng đăng nhập lại.");
                return;
            }

            string userName = objUser.UserName.ToLower();
            bool isNew = string.IsNullOrWhiteSpace(hdnTaskID.Value);

            HRS_Task item = new HRS_Task();
            if (!isNew)
            {
                long id;
                if (long.TryParse(hdnTaskID.Value, out id) && id > 0)
                    item.TaskID = id;
                else
                    isNew = true;
            }

            item.BeginTransaction();
            try
            {
                item.EmployeeID = employeeId;
                item.TaskTypeID = ParseInt(ddlTaskType.SelectedValue);
                item.CurrentPositionID = NormalizePositionId(EmployeeV2WebLookup.GetString(ddlCurrentPosition));
                item.PositionID = NormalizePositionId(EmployeeV2WebLookup.GetString(ddlPosition));
                item.OtherPositionID = NormalizePositionId(EmployeeV2WebLookup.GetString(ddlOtherPosition));
                item.DecidedNo = txtDecidedNo.Text.Trim();
                item.DecidedDate = ParseNullableDate(txtDecidedDate.Text);
                item.TaskFrom = ResolveTaskFromDate();
                item.TaskTo = ParseNullableDate(txtTaskTo.Text);
                item.IsSigned = chkIsSigned.Checked;
                item.DecidedDepartmentName = txtDecidedDepartmentName.Text.Trim();
                item.DecidedFullName = txtDecidedFullName.Text.Trim();
                item.ToOfficeName = txtToOfficeName.Text.Trim();
                item.ToDepartmentName = txtToDepartmentName.Text.Trim();
                item.Work = txtWork.Text.Trim();
                item.Description = txtDescription.Text.Trim();
                item.EndTask_DecidedNo = txtEndTask_DecidedNo.Text.Trim();
                item.EndTask_DecidedDate = ParseNullableDate(txtEndTask_DecidedDate.Text);

                bool result;
                if (isNew)
                {
                    item.CreatedUser = userName;
                    result = item.Add();
                }
                else
                {
                    item.UpdatedUser = userName;
                    result = item.Update();
                }

                if (!result)
                {
                    try { item.RollBackTransaction(); }
                    catch { }
                    string errMsg = GetTaskErrorMessage(item, isNew);
                    MsgBox.ShowWarning(errMsg);
                    hidOpenModal.Value = "1";
                    udpAll.Update();
                    RegisterShowModalScript();
                    return;
                }

                item.CommitTransaction();
                ClearModalFields(false);
                hidOpenModal.Value = string.Empty;
                udpAll.Update();
                RegisterHideModalScript();
                MsgBox.ShowInfo("Đã lưu thông tin công tác.");

                if (DataSaved != null)
                    DataSaved(this, EventArgs.Empty);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabCongTacEdit.Save: " + ex.Message);
                MsgBox.ShowError("Lỗi khi lưu thông tin công tác.");
            }
        }

        public void ApplyEditPermission()
        {
            if (btnSaveModal != null)
