        {
            string defaultMsg = isNew ? "Không thể thêm quá trình công tác." : "Không thể cập nhật quá trình công tác.";
            if (item == null || item.ErrorException == null)
                return defaultMsg;
            string msg = item.ErrorException.Message ?? string.Empty;
            if (msg.IndexOf("duplicate", StringComparison.OrdinalIgnoreCase) >= 0)
                return "Trùng lặp số quyết định!";
            return defaultMsg;
