        private static int ParseInt(string input)
        {
            if (string.IsNullOrWhiteSpace(input))
                return 0;
            int val;
            int.TryParse(input, out val);
            return val;
        }

        private static string SafeText(object value)
        {
            if (value == null || value == DBNull.Value)
                return string.Empty;
            return value.ToString().Trim();
        }

        private static string FormatDateForInput(DateTime? value)
        {
            if (value == null)
                return string.Empty;
            return value.Value.ToString("dd/MM/yyyy");
        }

        private static string NormalizePositionId(string positionId)
        {
            if (string.IsNullOrWhiteSpace(positionId))
                return null;
            return positionId.Trim();
        }

        private static DateTime? ParseNullableDate(string input)
        {
            if (string.IsNullOrWhiteSpace(input))
                return null;

            DateTime dt;
            string[] formats = { "dd/MM/yyyy", "d/M/yyyy", "yyyy-MM-dd", "yyyy/MM/dd" };

            if (DateTime.TryParseExact(input.Trim(), formats, CultureInfo.InvariantCulture, DateTimeStyles.None, out dt))
                return dt;

            if (DateTime.TryParse(input, CultureInfo.CurrentCulture, DateTimeStyles.None, out dt))
                return dt;

            return null;
        }
    }
